from pathlib import Path
p=Path('app/page.tsx')
s=p.read_text()
old="""      const strategyProgress=strategyDecisionProgress(p.id)\n      const strategyComplete=!!(p as any).strategy_completed\n      return <button key={p.id} className={`project-card ${is1688?'project-card-1688':''} ${overdueFlag?'project-card-overdue':''}`} onClick={()=>{openProject(p.id);const first=stages.find(s=>s.project_id===p.id)?.id;if(first)setExpanded({[first]:true})}}><div className=\"project-top\"><div><div className=\"project-heading-line\"><h2>{p.name}</h2><span className={`kind-badge ${is1688?'kind-1688':'kind-brand'}`}>{is1688?'1688 新品':'品牌新品'}</span>{overdueFlag&&<span className=\"pill pill-danger\">已逾期</span>}</div><p>{p.version||'-'} ・ 負責：{owner}</p></div><StatusPill text={p.status||'未設定'}/></div><div className=\"project-meta\"><span>上市日 <b>{p.launch_date||'-'}</b></span><span>正式價 <b>NT$ {p.retail_price??'-'}</b></span><span>團購價 <b>NT$ {p.group_price??'-'}</b></span><span>{is1688?'簡易工作':'執行工作'} <b>{is1688?`${pt.filter(t=>isDone(t.status)).length}/${pt.length}`:`${et.filter(t=>isDone(t.status)).length}/${et.filter(t=>countsInExecutionProgress(t.status)).length}`}</b></span></div>{is1688?<div className=\"single-progress\"><span>1688 上架進度 <b>{pct}%</b></span><div className=\"progress\"><i style={{width:`${pct}%`}}/></div></div>:<div className=\"dual-progress\"><div><span>策略管理 <b>{strategyComplete?'✓ 已完成':`${strategyProgress.done}/${strategyProgress.total} 已確認`}</b></span><div className=\"progress\"><i style={{width:`${strategyComplete?100:(strategyProgress.total?Math.round(strategyProgress.done/strategyProgress.total*100):0)}%`}}/></div></div><div><span>執行管理 <b>{et.length?`${ep}%`:'尚未建立'}</b></span><div className=\"progress execution-progress\"><i style={{width:`${ep}%`}}/></div></div></div>}</button>"""
new="""      const strategyProgress=strategyDecisionProgress(p.id)\n      const strategyComplete=!!(p as any).strategy_completed\n      const productComplete=productDataDone(p.id)\n      const executionDone=et.length>0 && et.filter(t=>t.status!=='不適用').every(t=>isDone(t.status))\n      return <button key={p.id} className={`project-card ${is1688?'project-card-1688':''} ${overdueFlag?'project-card-overdue':''}`} onClick={()=>{openProject(p.id);const first=stages.find(s=>s.project_id===p.id)?.id;if(first)setExpanded({[first]:true})}}><div className=\"project-top\"><div><div className=\"project-heading-line\"><h2>{p.name}</h2><span className={`kind-badge ${is1688?'kind-1688':'kind-brand'}`}>{is1688?'1688 新品':'品牌新品'}</span>{overdueFlag&&<span className=\"pill pill-danger\">已逾期</span>}</div><p>{p.version||'-'} ・ 負責：{owner}</p></div><StatusPill text={p.status||'未設定'}/></div><div className=\"project-meta\"><span>上市日 <b>{p.launch_date||'-'}</b></span><span>正式價 <b>NT$ {p.retail_price??'-'}</b></span><span>團購價 <b>NT$ {p.group_price??'-'}</b></span><span>{is1688?'簡易工作':'執行工作'} <b>{is1688?`${pt.filter(t=>isDone(t.status)).length}/${pt.length}`:`${et.filter(t=>isDone(t.status)).length}/${et.filter(t=>countsInExecutionProgress(t.status)).length}`}</b></span></div>{is1688?<div className=\"single-progress\"><span>1688 上架進度 <b>{pct}%</b></span><div className=\"progress\"><i style={{width:`${pct}%`}}/></div></div>:<div className=\"project-stage-strip\"><div className={productComplete?'stage-chip done':'stage-chip'}><small>01 產品資料</small><b>{productComplete?'✓ 已完成':'待完成'}</b></div><div className={strategyComplete?'stage-chip done':'stage-chip'}><small>02 新品策略</small><b>{strategyComplete?'✓ 已完成':strategyProgress.total?`${strategyProgress.done}/${strategyProgress.total} 已確認`:'尚未建立'}</b></div><div className={executionDone?'stage-chip done':'stage-chip'}><small>03 執行管理</small><b>{executionDone?'✓ 已完成':et.length?`${ep}%`:'尚未建立'}</b></div></div>}</button>"""
assert old in s
s=s.replace(old,new)
p.write_text(s)
